 </style>
 </head>
 <body><main class="shell"><header class="topbar"><div class="brand"><div class="brandmark">✦</div><div class="brandname">EMBERFALL<small>THE SHATTERED CROWN</small></div></div><div class="hud"><div class="hudgroup"><span class="hudlabel">VITALITY</span><div class="health" id="health"></div></div><div class="hudgroup xpbox"><span class="hudlabel">LEVEL <b id="level">01</b></span><div class="xpbar"><i id="xpbar"></i></div></div></div><div class="hudright"><div class="coin"><b>◈</b><span id="coins">00</span></div><button class="pausebtn" id="pause">Ⅱ &nbsp;PAUSE</button></div></header><section class="stage"><canvas id="game"></canvas><div class="toast" id="toast"></div><div class="overlay" id="overlay"><div class="panel"><div class="eyebrow" id="eyebrow">A LOST KINGDOM • A NEW LEGEND</div><h1 id="title">The crown<br>is waiting.</h1><p id="description">The old roads are crawling with things that should have stayed buried. Find better steel, guard your heart, and make your way to the citadel.</p><div class="objective"><i>⚔</i><span id="objective">Explore the Ashen Reach. Find gear. Reach the Crown Gate.</span></div><div class="actions"><button class="primary" id="play">BEGIN YOUR QUEST&nbsp; →</button><span class="subnote">PROGRESS SAVES LOCALLY</span></div></div></div><div class="touch"><div class="touchgroup left"><button data-key="left">◀</button><button data-key="right">▶</button></div><div class="touchgroup right"><button data-key="jump">↑</button><button class="attack" data-key="attack">⚔</button></div></div></section><footer class="bottom"><div class="gear"><span class="gearlabel">EQUIPPED</span><div class="gearitem"><span class="gearicon" id="weaponIcon">🪵</span><span class="geartext" id="weaponName">Bare hands<small id="weaponStat">ATK 1</small></span></div><div class="gearitem"><span class="gearicon" id="armorIcon">🧥</span><span class="geartext" id="armorName">Traveler's coat<small id="armorStat">DEF 0</small></span></div></div><div class="hint"><kbd>A</kbd><kbd>D</kbd> MOVE &nbsp; <kbd>SPACE</kbd> JUMP &nbsp; <kbd>J</kbd> ATTACK</div><div class="mobiletip">Tap controls to move • find the glowing gear</div></footer></main>
 <script>
+(()=>{
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+const ui={health:document.getElementById('health'),level:document.getElementById('level'),xpbar:document.getElementById('xpbar'),coins:document.getElementById('coins'),overlay:document.getElementById('overlay'),title:document.getElementById('title'),desc:document.getElementById('description'),eyebrow:document.getElementById('eyebrow'),objective:document.getElementById('objective'),play:document.getElementById('play'),toast:document.getElementById('toast'),weaponIcon:document.getElementById('weaponIcon'),weaponName:document.getElementById('weaponName'),weaponStat:document.getElementById('weaponStat'),armorIcon:document.getElementById('armorIcon'),armorName:document.getElementById('armorName'),armorStat:document.getElementById('armorStat')};
+let W=960,H=540,dpr=1,camera=0,last=0,toastTimer=0,mode='menu',time=0,shake=0;
+const worldWidth=3900, keys={left:false,right:false,jump:false,attack:false};
+const weapons=[{name:'Bare hands',icon:'🪵',power:1},{name:'Rusty blade',icon:'🗡️',power:2},{name:'Ashen axe',icon:'🪓',power:3},{name:'Moonsteel',icon:'⚔️',power:5}];
+const armors=[{name:"Traveler's coat",icon:'🧥',def:0},{name:'Scrap cuirass',icon:'🥋',def:1},{name:'Mossguard plate',icon:'🛡️',def:2},{name:'Crownward mail',icon:'🛡️',def:3}];
+let player,enemies,pickups,particles,coins,level,xp,checkpoints;
+const zones=[{name:'ASHEN REACH',from:0,to:1150,sky:['#182b3a','#7f665a'],accent:'#e9a85d'},{name:'MIRE OF WHISPERS',from:1150,to:2450,sky:['#142f35','#486b5d'],accent:'#86c8a4'},{name:'CROWNWARD PASS',from:2450,to:3900,sky:['#22283a','#8e5962'],accent:'#f2b56c'}];
+function groundY(){return H-73}
+function platformList(){let b=groundY();return [{x:245,y:b-105,w:142},{x:475,y:b-175,w:112},{x:710,y:b-112,w:150},{x:960,y:b-195,w:125},{x:1195,y:b-130,w:145},{x:1415,y:b-205,w:120},{x:1645,y:b-125,w:170},{x:1900,y:b-188,w:125},{x:2130,y:b-115,w:150},{x:2370,y:b-190,w:135},{x:2590,y:b-120,w:165},{x:2845,y:b-204,w:120},{x:3065,y:b-125,w:175},{x:3340,y:b-195,w:138},{x:3570,y:b-120,w:145}];}
+let platforms=[];
+function makeWorld(){let b=groundY();platforms=platformList();
+ enemies=[{x:380,y:b-30,type:'slime',hp:2,dir:-1,min:300,max:445},{x:620,y:b-28,type:'crawler',hp:2,dir:1,min:555,max:690},{x:875,y:b-33,type:'brute',hp:4,dir:-1,min:825,max:940},{x:1090,y:b-29,type:'slime',hp:2,dir:1,min:1060,max:1155},{x:1325,y:b-30,type:'wisp',hp:2,dir:-1,min:1240,max:1395},{x:1535,y:b-30,type:'crawler',hp:3,dir:1,min:1460,max:1610},{x:1780,y:b-36,type:'brute',hp:5,dir:-1,min:1700,max:1860},{x:2015,y:b-29,type:'slime',hp:3,dir:1,min:1980,max:2110},{x:2245,y:b-31,type:'wisp',hp:3,dir:-1,min:2180,max:2340},{x:2475,y:b-34,type:'crawler',hp:4,dir:1,min:2400,max:2560},{x:2730,y:b-37,type:'brute',hp:6,dir:-1,min:2670,max:2820},{x:2960,y:b-30,type:'slime',hp:4,dir:1,min:2900,max:3040},{x:3225,y:b-34,type:'wisp',hp:4,dir:-1,min:3160,max:3310},{x:3450,y:b-38,type:'brute',hp:7,dir:1,min:3380,max:3540},{x:3715,y:b-45,type:'knight',hp:12,dir:-1,min:3620,max:3810}];
+ pickups=[{x:285,y:b-145,type:'weapon',idx:1},{x:515,y:b-215,type:'coin'},{x:770,y:b-150,type:'armor',idx:1},{x:1000,y:b-235,type:'coin'},{x:1240,y:b-170,type:'coin'},{x:1460,y:b-245,type:'weapon',idx:2},{x:1695,y:b-165,type:'coin'},{x:1940,y:b-228,type:'armor',idx:2},{x:2170,y:b-155,type:'coin'},{x:2410,y:b-230,type:'coin'},{x:2640,y:b-160,type:'weapon',idx:3},{x:2880,y:b-245,type:'coin'},{x:3110,y:b-165,type:'armor',idx:3},{x:3380,y:b-235,type:'coin'},{x:3600,y:b-160,type:'coin'}].map(p=>({...p,got:false,phase:Math.random()*6}));
+}
+function reset(){let save=localStorage.getItem('emberfall-save');let data=save?JSON.parse(save):{};coins=0;level=1;xp=0;player={x:82,y:groundY()-38,vx:0,vy:0,w:25,h:38,face:1,hp:5,maxHp:5,weapon:0,armor:0,ground:false,attack:0,attackCd:0,invul:0,dead:false};particles=[];makeWorld();if(data.best){toast('BEST RUN: '+data.best+' COINS');}}
+function save(){try{localStorage.setItem('emberfall-save',JSON.stringify({best:Math.max(coins,JSON.parse(localStorage.getItem('emberfall-save')||'{}').best||0)}))}catch(e){}}
+function resize(){let r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);canvas.width=Math.floor(r.width*dpr);canvas.height=Math.floor(r.height*dpr);W=960;H=canvas.height/(canvas.width/W);if(player){let shift=H-groundY();player.y+=shift;makeWorld();}}
+function say(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastTimer=2.2}
+function updateHUD(){ui.health.innerHTML='';for(let i=0;i<player.maxHp;i++){let s=document.createElement('span');s.className='heart'+(i>=player.hp?' off':'');s.textContent='♥';ui.health.appendChild(s)}ui.level.textContent=String(level).padStart(2,'0');ui.xpbar.style.width=Math.min(100,xp/10*100)+'%';ui.coins.textContent=String(coins).padStart(2,'0');let w=weapons[player.weapon],a=armors[player.armor];ui.weaponIcon.textContent=w.icon;ui.weaponName.innerHTML=w.name+'<small>ATK '+w.power+'</small>';ui.armorIcon.textContent=a.icon;ui.armorName.innerHTML=a.name+'<small>DEF '+a.def+'</small>';}
+function zoneAt(x){return zones.find(z=>x>=z.from&&x<z.to)||zones[2]}
+function rand(a,b){return a+Math.random()*(b-a)}

input.newString:
function rand(a,b){return a+Math.random()*(b-a)}
function isPit(x){return [[520,595],[1125,1190],[1840,1905],[2540,2600],[3290,3350]].some(g=>x>g[0]&&x<g[1])}
function burst(x,y,color,n=9){for(let i=0;i<n;i++)particles.push({x,y,vx:rand(-135,135),vy:rand(-190,25),life:rand(.35,.8),max:.8,color,size:rand(2,5)})}
function damage(amount,source){if(player.invul>0||mode!=='play')return;let dealt=Math.max(1,amount-armors[player.armor].def);player.hp-=dealt;player.invul=1.15;player.vx=player.x<source?-180:180;player.vy=-230;shake=8;burst(player.x+12,player.y+18,'#ff7468',10);say('HIT!  −'+dealt+' VITALITY');updateHUD();if(player.hp<=0){player.dead=true;mode='dead';save();showOverlay('fallen')}}
function attack(){if(player.attackCd>0||mode!=='play')return;player.attack=.22;player.attackCd=.38;let range=62+weapons[player.weapon].power*3,hit=false;for(let e of enemies){if(e.hp<=0||Math.abs((e.x+14)-(player.x+12))>range||Math.abs((e.y+15)-(player.y+18))>46)continue;if((player.face>0&&e.x<player.x)||(player.face<0&&e.x>player.x+player.w))continue;e.hp-=weapons[player.weapon].power;hit=true;burst(e.x+14,e.y+13,e.type==='wisp'?'#9cf2cf':'#f5c46b',7);e.x+=player.face*17;if(e.hp<=0){coins+=e.type==='knight'?12:e.type==='brute'?4:2;xp+=e.type==='knight'?8:2;if(xp>=10){xp-=10;level++;player.maxHp=Math.min(8,player.maxHp+1);player.hp=Math.min(player.maxHp,player.hp+1);say('LEVEL UP!  VITALITY RESTORED')}else say('ENEMY DOWN  +'+(e.type==='knight'?12:e.type==='brute'?4:2)+' ◈');updateHUD();}}if(hit)shake=3}
function update(dt){time+=dt;if(mode!=='play')return;dt=Math.min(dt,.035);let p=player;p.attack=Math.max(0,p.attack-dt);p.attackCd=Math.max(0,p.attackCd-dt);p.invul=Math.max(0,p.invul-dt);let accel=keys.left?-1:keys.right?1:0;if(accel){p.vx+=accel*1100*dt;p.face=accel}else p.vx*=Math.pow(.001,dt);p.vx=Math.max(-225,Math.min(225,p.vx));if(keys.jump&&p.ground){p.vy=-445;p.ground=false;burst(p.x+12,p.y+37,'#d7c6a4',5)}p.vy=Math.min(650,p.vy+1050*dt);let oldY=p.y;p.x=Math.max(0,Math.min(worldWidth-p.w,p.x+p.vx*dt));p.y+=p.vy*dt;p.ground=false;
 let b=groundY();if(p.vy>=0&&!isPit(p.x+p.w/2)&&oldY+p.h<=b&&p.y+p.h>=b){p.y=b-p.h;p.vy=0;p.ground=true}
 for(let plat of platforms){if(p.vy>=0&&oldY+p.h<=plat.y&&p.y+p.h>=plat.y&&p.x+p.w>plat.x&&p.x<plat.x+plat.w){p.y=plat.y-p.h;p.vy=0;p.ground=true}}
 if(p.y>H+120){damage(99,p.x-1);if(mode!=='play')return;p.x=Math.max(70,p.x-110);p.y=b-100;p.vy=-80}
 if(keys.attack)attack();
 for(let e of enemies){if(e.hp<=0)continue;e.x+=e.dir*(e.type==='brute'?25:e.type==='knight'?38:e.type==='wisp'?43:34)*dt;if(e.x<e.min||e.x>e.max)e.dir*=-1;if(Math.abs(e.x-p.x)<30&&Math.abs(e.y-p.y)<35)damage(e.type==='knight'?2:1,e.x+14)}
 for(let item of pickups){if(item.got)continue;let iy=item.y+Math.sin(time*2.7+item.phase)*5;if(Math.abs((p.x+p.w/2)-item.x)<28&&Math.abs((p.y+p.h/2)-iy)<34){item.got=true;if(item.type==='coin'){coins++;say('SHARD FOUND  +1 ◈');burst(item.x,iy,'#f3d16f',10)}else if(item.type==='weapon'&&item.idx>p.weapon){p.weapon=item.idx;say('WEAPON EQUIPPED  '+weapons[item.idx].name.toUpperCase());burst(item.x,iy,'#e5ad5d',14)}else if(item.type==='armor'&&item.idx>p.armor){p.armor=item.idx;say('ARMOR EQUIPPED  '+armors[item.idx].name.toUpperCase());burst(item.x,iy,'#8de0c2',14)}else{coins+=2;say('DUPLICATE GEAR  +2 ◈')}updateHUD()}}
 for(let q of particles){q.x+=q.vx*dt;q.y+=q.vy*dt;q.vy+=400*dt;q.life-=dt}particles=particles.filter(q=>q.life>0);
 camera=Math.max(0,Math.min(worldWidth-W,p.x-W*.36));if(p.x>worldWidth-105){mode='won';save();showOverlay('won')}
 if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)ui.toast.classList.remove('show')}
}
function showOverlay(which){ui.overlay.classList.remove('hidden');if(which==='won'){ui.eyebrow.textContent='THE CROWNWARD CITADEL';ui.title.innerHTML='A crown<br>rekindled.';ui.desc.textContent='The Shattered Crown is whole again. The old roads will remember your name.';ui.objective.textContent='You crossed the Ashen Reach and reclaimed the citadel.';ui.play.textContent='PLAY AGAIN  →'}else{ui.eyebrow.textContent='THE ROAD IS NOT FORGOTTEN';ui.title.innerHTML='The dark<br>claims another.';ui.desc.textContent='You fought bravely, but the road is unforgiving. Gather gear, watch your footing, and try again.';ui.objective.textContent='Your run ended with '+coins+' shards collected.';ui.play.textContent='RISE AGAIN  →'} }
function begin(){if(mode==='dead'||mode==='won')reset();mode='play';ui.overlay.classList.add('hidden');last=performance.now()}

