function begin(){if(mode==='dead'||mode==='won')reset();mode='play';ui.overlay.classList.add('hidden');last=performance.now()}
function rr(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawBackground(){let z=zoneAt(camera+W*.5),g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,z.sky[0]);g.addColorStop(1,z.sky[1]);ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
 // distant moon and drifting fireflies
 let cx=760-camera*.08%1100;ctx.fillStyle='#f6d8a333';ctx.beginPath();ctx.arc((cx+1100)%1100,91,36,0,Math.PI*2);ctx.fill();ctx.fillStyle='#f7dca8';ctx.beginPath();ctx.arc((cx+1100)%1100,91,21,0,Math.PI*2);ctx.fill();
 for(let i=0;i<5;i++){let x=((i*255-camera*.12)%1250+1250)%1250-100;let y=H*.36+i%3*24;ctx.fillStyle='#f0d99b88';ctx.beginPath();ctx.arc(x,y,1.3,0,7);ctx.fill()}
 for(let layer=0;layer<3;layer++){let par=.12+layer*.11,base=H*(.56+layer*.075),step=260+layer*90,off=-(camera*par%step);ctx.beginPath();ctx.moveTo(-step, H);for(let x=-step+off;x<W+step;x+=step){let peak=base-70-(Math.sin((x+camera*par)*.012+layer)*25);ctx.lineTo(x,peak);ctx.lineTo(x+step*.5,base+30);ctx.lineTo(x+step,base-12)}ctx.lineTo(W,H);ctx.closePath();ctx.fillStyle=['#273b45','#23353c','#202e34'][layer];ctx.fill();}
